<?php

namespace dokuwiki\plugin\diagrams\test;

use DokuWikiTest;

/**
 * Tests for the diagram detection in the helper
 *
 * @group plugin_diagrams
 * @group plugins
 */
class HelperTest extends DokuWikiTest
{
    protected $pluginsEnabled = ['diagrams'];

    /** XML prolog, comment and doctype as written by diagrams.net SVG exports */
    protected const PROLOG = '<?xml version="1.0" encoding="UTF-8"?>' . "\n" .
    '<!-- Do not edit this file with editors other than draw.io -->' . "\n" .
    '<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN" "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">' . "\n";

    /** a minimal diagram model as embedded in the content attribute */
    protected const MODEL = '&lt;diagram name=&quot;Page-1&quot; id=&quot;abc&quot;&gt;&lt;mxGraphModel&gt;&lt;root&gt;' .
    '&lt;mxCell id=&quot;0&quot; /&gt;&lt;/root&gt;&lt;/mxGraphModel&gt;&lt;/diagram&gt;&lt;/mxfile&gt;';

    /** a minimal SVG body */
    protected const BODY = '><defs/><g><rect x="0" y="0" width="120" height="60" fill="#ffffff" stroke="#000000"/></g></svg>';

    /**
     * Build an SVG the way diagrams.net exports it
     *
     * @param string $mxfile the attributes of the embedded mxfile element
     * @param string $rootAttributes additional attributes on the SVG root element
     * @param string $prolog what comes before the SVG root element
     * @return string
     */
    protected function diagramSvg($mxfile, $rootAttributes = '', $prolog = self::PROLOG)
    {
        return $prolog .
            '<svg xmlns="http://www.w3.org/2000/svg"' . $rootAttributes .
            ' xmlns:xlink="http://www.w3.org/1999/xlink" version="1.1" width="121px" height="61px"' .
            ' viewBox="-0.5 -0.5 121 61" content="&lt;mxfile ' . $mxfile . '&gt;' . self::MODEL . '"' .
            self::BODY;
    }

    /**
     * @return array
     */
    public function provideDiagrams()
    {
        $browserAgent = 'agent=&quot;Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 ' .
            '(KHTML, like Gecko) Chrome/138.0.0.0 Safari/537.36&quot;';

        return [
            'saved by this plugin' => [
                $this->diagramSvg(
                    'host=&quot;embed.diagrams.net&quot; ' . $browserAgent . ' version=&quot;26.1.1&quot;'
                ),
            ],
            'draw.io desktop' => [
                $this->diagramSvg(
                    'host=&quot;Electron&quot; agent=&quot;Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 ' .
                    '(KHTML, like Gecko) draw.io/24.7.17 Chrome/128.0.6613.36 Electron/32.0.1 Safari/537.36&quot;'
                ),
            ],
            'app.diagrams.net' => [
                $this->diagramSvg(
                    'host=&quot;app.diagrams.net&quot; ' . $browserAgent . ' version=&quot;26.1.1&quot;',
                    ' style="background: transparent; background-color: transparent; color-scheme: light dark;"'
                ),
            ],
            'app.diagrams.net without comment' => [
                $this->diagramSvg(
                    'host=&quot;app.diagrams.net&quot; modified=&quot;2020-03-28T04:01:53.505Z&quot; ' .
                    $browserAgent . ' etag=&quot;C0wCoHS6CW0lW-3_ueOR&quot; version=&quot;12.9.3&quot;',
                    '',
                    '<?xml version="1.0" encoding="UTF-8"?>' . "\n" .
                    '<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN" ' .
                    '"http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">' . "\n"
                ),
            ],
            'VS Code extension' => [
                $this->diagramSvg('host=&quot;65bd71144e&quot;', ' host="65bd71144e"', ''),
            ],
        ];
    }

    /**
     * @dataProvider provideDiagrams
     * @param string $svg
     */
    public function testIsDiagram($svg)
    {
        /** @var \helper_plugin_diagrams $helper */
        $helper = plugin_load('helper', 'diagrams');
        $this->assertTrue($helper->isDiagram($svg));
    }

    /**
     * @dataProvider provideDiagrams
     * @param string $svg
     */
    public function testIsDiagramFile($svg)
    {
        $file = TMP_DIR . '/diagram.svg';
        file_put_contents($file, $svg);

        /** @var \helper_plugin_diagrams $helper */
        $helper = plugin_load('helper', 'diagrams');
        $this->assertTrue($helper->isDiagramFile($file));
    }

    /**
     * @return array
     */
    public function provideNonDiagrams()
    {
        return [
            'empty' => [''],
            'not an SVG' => ['<html><body>&lt;mxfile host=&quot;app.diagrams.net&quot;&gt;</body></html>'],
            'plain SVG' => [
                '<?xml version="1.0" encoding="UTF-8"?>' . "\n" .
                '<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10"><rect width="10" height="10"/></svg>',
            ],
            'other content attribute' => [
                '<svg xmlns="http://www.w3.org/2000/svg" content="something else" width="10" height="10"></svg>',
            ],
            'mxfile outside the root element' => [
                '<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10">' .
                '<text content="&lt;mxfile host=&quot;app.diagrams.net&quot;&gt;">x</text></svg>',
            ],
        ];
    }

    /**
     * @dataProvider provideNonDiagrams
     * @param string $svg
     */
    public function testIsNoDiagram($svg)
    {
        /** @var \helper_plugin_diagrams $helper */
        $helper = plugin_load('helper', 'diagrams');
        $this->assertFalse($helper->isDiagram($svg));
    }
}
